const SERVER_NAME='OrbitFS MCP', SERVER_VERSION='1.5.0';
const optimizedWidgetHtml=widgetHtml.replace(/setTimeout\(async\(\)=>\{try\{await call\('orbitfs_ui_state',[\s\S]*?\}\},0\);(?=\s*<\/script>)/,'');
const requestIdentity=new AsyncLocalStorage<any>();
const activeIdentity=()=>{const identity=requestIdentity.getStore();if(!identity)throw Object.assign(new Error('MCP request identity is unavailable'),{status:500,code:'MCP_IDENTITY_UNAVAILABLE'});return identity;};
const identityProxy:any=new Proxy({}, {
  get(_target,property){return activeIdentity()[property as any];},
  set(_target,property,value){activeIdentity()[property as any]=value;return true;},
  has(_target,property){return property in activeIdentity();},
  ownKeys(){return Reflect.ownKeys(activeIdentity());},
  getOwnPropertyDescriptor(_target,property){const descriptor=Object.getOwnPropertyDescriptor(activeIdentity(),property);return descriptor?{...descriptor,configurable:true}:{configurable:true,enumerable:true,writable:true,value:activeIdentity()[property as any]};}
});
let sharedRuntimePromise:Promise<{server:McpServer;transport:WebStandardStreamableHTTPServerTransport}>|null=null;
const outputSchema=z.object({ok:z.boolean().optional(),message:z.string().optional(),workspaceId:z.string().optional()}).passthrough();
const textResult=(message:string,data:any={},meta:any={})=>({content:[{type:'text' as const,text:message}],structuredContent:{ok:true,message,...data},_meta:{...meta,orbitfsUiState:data}});
const contentResult=(content:string,data:any={},meta:any={})=>({content:[{type:'text' as const,text:content}],structuredContent:{ok:true,...data},_meta:{...meta,orbitfsUiState:data}});
const asError=(error:any)=>({content:[{type:'text' as const,text:String(error?.message||error||'OrbitFS request failed')}],isError:true});
const requireAdmin=(identity:any)=>{if(!['owner','admin'].includes(String(identity.role||'').toLowerCase()))throw Object.assign(new Error('System Owner or Admin required'),{status:403,code:'SYSTEM_ROLE_REQUIRED'});};

function registerResources(server:McpServer){
  const home='ui://orbitfs/home-v8.html', studio='ui://orbitfs/studio-v8.html';
  const homeMeta:any={ui:{prefersBorder:true,csp:{connectDomains:[],resourceDomains:[]}},'openai/widgetDescription':'OrbitFS workspace files, context and upload controls','openai/widgetPrefersBorder':true};
  for(const uri of [home,'ui://orbitfs/home-v7.html']) registerAppResource(server,'OrbitFS Home',uri,{description:'OrbitFS workspace files, context and upload controls',mimeType:RESOURCE_MIME_TYPE,_meta:homeMeta},async()=>({contents:[{uri,mimeType:RESOURCE_MIME_TYPE,text:optimizedWidgetHtml,_meta:homeMeta}]}));  const studioMeta:any={ui:{prefersBorder:true,csp:{connectDomains:[],resourceDomains:[]}},'openai/widgetDescription':'OrbitFS Studio chat-first writing and documentation','openai/widgetPrefersBorder':true};
  for(const uri of [studio,'ui://orbitfs/studio-v7.html','ui://orbitfs/studio-v6.html','ui://orbitfs/studio-v5.html','ui://orbitfs/studio-v4.html']){
    registerAppResource(server,'OrbitFS Studio',uri,{description:'OrbitFS Studio chat-first writing and documentation',mimeType:RESOURCE_MIME_TYPE,_meta:studioMeta},async()=>({contents:[{uri,mimeType:RESOURCE_MIME_TYPE,text:studioWidgetHtml,_meta:studioMeta}]}));
  }
  return {
    homeMeta:{ui:{resourceUri:home},'openai/outputTemplate':home,'openai/widgetAccessible':true,'openai/widgetPrefersBorder':true,'openai/widgetDescription':'OrbitFS workspace files, context and upload controls'},
    studioMeta:{ui:{resourceUri:studio},'openai/outputTemplate':studio,'openai/widgetAccessible':true,'openai/widgetPrefersBorder':true,'openai/widgetDescription':'OrbitFS Studio chat-first writing and documentation'},
    appOnly:{'openai/widgetAccessible':true,ui:{visibility:['app']}}
  };
}

async function buildStartupUiConfig(identity:any, workspaceId:string, strength:string, projectId:string|undefined, profiles:any) {
  const [startup, projects] = await Promise.all([getStartup(workspaceId), listMcpProjects(workspaceId)]);
  const selectedProject = projectId
    ? projects.find((p:any)=>String(p.id)===String(projectId)) || null
    : projects.find((p:any)=>(startup.projectIds||[]).map(String).includes(String(p.id))) || null;
  const scopeId = selectedProject?.id || null;
  const [presets, presetMetadata, presetBundles] = await Promise.all([
    getPresets(workspaceId, scopeId), getPresetMetadata(workspaceId, scopeId), getPresetBundles(workspaceId, scopeId)
  ]);
  const preset = strength || startup.strength || 'medium';
  const selectedPreset = presets?.[preset] || {};
  const byProfile = new Map((profiles.profiles||[]).map((p:any)=>[String(p.id),p]));
  const byBundle = new Map((profiles.profileBundles||[]).map((b:any)=>[String(b.id),b]));
  const hydrateBundle = (id:any) => {
    const bundle:any = byBundle.get(String(id));
    return bundle ? { ...bundle, profiles:(bundle.profileIds||[]).map((pid:any)=>byProfile.get(String(pid))).filter(Boolean) } : null;
  };
  const defaultProfiles = (startup.defaultProfileIds||[]).map((id:any)=>byProfile.get(String(id))).filter(Boolean);
  const defaultProfileBundles = (startup.defaultProfileBundleIds||[]).map(hydrateBundle).filter(Boolean);
  const presetProfiles = (selectedPreset.profileIds||[]).map((id:any)=>byProfile.get(String(id))).filter(Boolean);
  const presetProfileBundles = (selectedPreset.profileBundleIds||[]).map(hydrateBundle).filter(Boolean);
  const projectBundles = selectedProject ? await projectBundleAssignments(String(selectedProject.id)) : [];
  const assignedMap = new Map<string,any>();
  for (const item of [...(presetBundles?.[preset]||[]), ...projectBundles]) assignedMap.set(String(item.bundleId), item);
  const assignedContextBundles = [...assignedMap.values()];
  return {
    startup,
    projects: projects.map((p:any)=>({id:String(p.id),name:p.name,description:p.description||''})),
    project: selectedProject,
    presetMetadata,
    defaultItems: startup.defaultItems||[],
    projectItems: selectedProject?.items||[],
    presetItems: selectedPreset.items||[],
    assignedBundles: assignedContextBundles,
    instructions: selectedProject?.instructions || startup.instructions || '',
    aiBehaviour: selectedProject?.ai_behaviour || startup.aiBehaviour || '',
    startupSelection:{ defaultItems:startup.defaultItems||[], projectItems:selectedProject?.items||[], presetItems:selectedPreset.items||[], defaultProfiles, defaultProfileBundles, presetProfiles, presetProfileBundles, assignedContextBundles }
  };
}


async function uiState(identity:any,workspaceId?:string,strength?:string,projectId?:string){
  const requested = workspaceId && workspaceId !== 'default' ? workspaceId : undefined;
  let picked:any=await chooseWorkspace(identity,requested);
  if (!requested && picked.workspace?.mcp_ui_enabled === false) {
    const preferred = picked.workspaces.find((w:any)=>w.mcp_ui_enabled !== false);
    if (preferred) picked = await chooseWorkspace(identity,String(preferred.id));
  }
  const ws=picked.workspace;
  const uiWorkspaces=picked.workspaces.filter((w:any)=>w.mcp_ui_enabled !== false);
  const [receipt,bundles,profiles]=await Promise.all([
    getActiveContext(identity,ws.id),
    listContextBundles(ws.id).catch(()=>[]),
    listProfilesCloud(identity,ws.id).catch(()=>({enabled:false,profiles:[],profileBundles:[],settings:{},permissions:{},slots:{master:null,additional:null}}))
  ]);
  const changes=await inspectContextChanges(identity,ws.id,receipt);
  const config=strength?await buildStartupUiConfig(identity,ws.id,strength,projectId,profiles).catch(()=>null):null;
  return {
    workspaceId:ws.id,workspaceName:ws.name,
    workspaces:uiWorkspaces.map((w:any)=>({id:String(w.id),name:w.name,status:w.status||'active',permission:w.permission})),
    strength:strength||null,projectId:projectId||config?.project?.id||null,
    dashboard:{user:{username:identity.username,systemRole:identity.role},workspace:{id:String(ws.id),name:ws.name,status:ws.status||'active',role:ws.permission||ws.role||'viewer'}},
    context:compactContext(receipt,changes.changedFiles),activeContext:receipt,activeFiles:receipt?.files||[],bundles,
    profiles:profiles.profiles||[],profileBundles:profiles.profileBundles||[],settings:profiles.settings||{},permissions:profiles.permissions||{},slots:profiles.slots||{master:null,additional:null},
    profileSystemEnabled:profiles.enabled===true,canWrite:identity.scopes?.has?.('orbitfs:write')&&identity.clientPermissions?.write!==false,
    ...(config?{config}:{})
  };
}

