  registerAppTool(server,'orbitfs',{title:'Open OrbitFS',description:'Open the OrbitFS embedded UI. Only call when the user explicitly asks to open OrbitFS.',inputSchema:{workspaceId:z.string().optional(),strength:z.enum(['low','medium','high','custom1','custom2']).optional(),projectId:z.string().optional()},annotations:ro,_meta:homeMeta},async({workspaceId,strength,projectId}:any)=>({content:[{type:'text',text:'OrbitFS opened.'}],structuredContent:{ok:true,message:'OrbitFS opened.'},_meta:{...homeMeta,orbitfsUiState:await uiState(identity,workspaceId,strength,projectId)}}));
  registerAppTool(server,'studio',{title:'Open Studio',description:'Open the OrbitFS Studio ChatGPT UI when the user asks to open, browse, journal in, or work with Studio.',inputSchema:{workspaceId:z.string().optional(),view:z.enum(['home','journals','documents','library']).optional()},annotations:ro,_meta:studioMeta},async({workspaceId,view='home'}:any)=>{const p:any=await chooseWorkspace(identity,workspaceId),state:any=await buildStudioUiState(identity,p.workspace.id);state.initialView=view;state.workspaces=p.workspaces.map((w:any)=>({id:String(w.id),name:w.name,status:w.status||'active'}));return {content:[{type:'text',text:'Studio opened.'}],structuredContent:{ok:true,message:'Studio opened.',workspaceId:p.workspace.id},_meta:{...studioMeta,studioUiState:state}};});
  registerAppTool(server,'ventmode',{title:'Open Studio Vent Mode',description:'Compatibility command: ventmode. Open OrbitFS Studio with Vent Mode enabled for the current or selected workspace.',inputSchema:{workspaceId:z.string().optional()},annotations:rw,_meta:studioMeta},async({workspaceId}:any)=>{const p:any=await chooseWorkspace(identity,workspaceId);setStudioModeCloud(identity,p.workspace.id,'vent');const state:any=await buildStudioUiState(identity,p.workspace.id);state.initialView='journals';state.workspaces=p.workspaces.map((w:any)=>({id:String(w.id),name:w.name,status:w.status||'active'}));return {content:[{type:'text',text:'Studio opened in Vent Mode.'}],structuredContent:{ok:true,message:'Studio opened in Vent Mode.',workspaceId:p.workspace.id},_meta:{...studioMeta,studioUiState:state}};});
  reg('orbitfs_ui_state','OrbitFS internal UI state','Internal app-only state endpoint for the embedded OrbitFS widget.',{workspaceId:z.string().optional(),strength:z.enum(['low','medium','high','custom1','custom2']).optional(),projectId:z.string().optional()},async({workspaceId,strength,projectId}:any)=>textResult('OrbitFS UI state refreshed.',{}, {...appOnly,orbitfsUiState:await uiState(identity,workspaceId,strength,projectId)}),ro,appOnly);
  reg('refresh_ui','Refresh OrbitFS UI','Refresh OrbitFS workspace access and rehydrate the embedded UI.',{workspaceId:z.string().optional(),strength:z.enum(['low','medium','high','custom1','custom2']).optional(),projectId:z.string().optional()},async({workspaceId,strength,projectId}:any)=>{const perms=await refreshPermissionsCloud(identity),state=await uiState(identity,workspaceId,strength,projectId);return textResult(`OrbitFS refreshed. ${perms.workspaceIds.length} workspace${perms.workspaceIds.length===1?'':'s'} available.`,{workspaceCount:perms.workspaceIds.length}, {...homeMeta,orbitfsUiState:state});});  reg('load_defaults','Load OrbitFS defaults','Load selected workspace default files and profiles into active context.',{workspaceId:z.string(),projectId:z.string().optional(),maxFiles:z.number().int().positive().max(500).optional(),maxCharacters:z.number().int().positive().max(5000000).optional()},async(a:any)=>{const r=await runStartupCloud(identity,a.workspaceId,'medium',a.projectId,true,a.maxFiles||250,a.maxCharacters||1500000);return textResult(r.loaded.length?`Loaded ${r.loaded.length} default item${r.loaded.length===1?'':'s'} into OrbitFS context.`:'No default items are configured for this workspace.',{workspaceId:a.workspaceId,loadedCount:r.loaded.length,charactersLoaded:r.total,errorCount:r.errors.length}, {orbitfsUiState:{workspaceId:a.workspaceId,context:compactContext(r.receipt)}});},rw);
  reg('run_startup','Run OrbitFS workspace startup','Manual startup action. Load always-loaded and selected preset content only when explicitly requested.',{workspaceId:z.string(),strength:z.enum(['low','medium','high','custom1','custom2']),projectId:z.string().optional()},async(a:any)=>{const r=await runStartupCloud(identity,a.workspaceId,a.strength,a.projectId,false,250);return textResult(`Startup loaded ${r.loaded.length} item${r.loaded.length===1?'':'s'} (${r.total} chars)${r.errors.length?`, ${r.errors.length} failed`:''}.`,{workspaceId:a.workspaceId,loadedCount:r.loaded.length,charactersLoaded:r.total,errorCount:r.errors.length},{orbitfsUiState:{workspaceId:a.workspaceId,context:compactContext(r.receipt)}});},rw);
  reg('context_status','OrbitFS context status','Show compact active-context status and whether source files changed.',{workspaceId:z.string()},async({workspaceId}:any)=>{const receipt=await getActiveContext(identity,workspaceId),changes=await inspectContextChanges(identity,workspaceId,receipt),summary=compactContext(receipt,changes.changedFiles);return textResult(`${summary.state} · ${summary.files} items · ${summary.charactersLabel} chars`,{workspaceId,context:summary,changedFiles:changes.changedFiles});});
  reg('context_explain','Explain OrbitFS context','Explain the currently loaded context items, sources, owners and bundle relationships.',{workspaceId:z.string()},async({workspaceId}:any)=>{const r=await getActiveContext(identity,workspaceId);const files=(r?.files||[]).map((x:any)=>({path:x.path,source:x.source,owners:x.contextOwners||[],required:!!x.required,characters:Number(x.characters||0),warning:x.warning||''}));return textResult(files.length?files.map((x:any)=>`- ${x.path} · ${x.source||'manual'} · ${x.characters} chars${x.owners.length?` · ${x.owners.join(', ')}`:''}`).join('\n'):'No active context.',{workspaceId,contextId:r?.contextId||null,items:files,bundles:r?.bundles||[]});});
  reg('get_active_context','Get active OrbitFS context','Return the exact context receipt currently active for a workspace.',{workspaceId:z.string()},async({workspaceId}:any)=>{const r=await getActiveContext(identity,workspaceId),c=await inspectContextChanges(identity,workspaceId,r);return textResult(r?`${(r.files||[]).length} context item(s) active.`:'No active context.',{workspaceId,receipt:r,context:compactContext(r,c.changedFiles)});});
